def mosque_svg(cap):
    """Coded flat illustration standing in for the uncaptioned photograph of the Faisal Mosque, Islamabad, below the Margalla hills."""
    minaret = lambda x: f'<rect x="{x - 4}" y="60" width="8" height="160" fill="#f4f4f4" stroke="#9aa3ab"/><polygon points="{x - 4},60 {x + 4},60 {x},30" fill="#e6e6e6" stroke="#9aa3ab"/>'
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 290" role="img" aria-label="{cap}">'
            '<rect width="480" height="290" fill="#9fc6e6"/>'
            '<polygon points="0,150 60,110 130,130 210,95 300,120 380,100 480,135 480,290 0,290" fill="#3f6b45"/>'
            + ''.join(minaret(x) for x in (70, 160, 330, 410)) +
            '<polygon points="140,220 245,120 350,220" fill="#f6f6f6" stroke="#9aa3ab" stroke-width="2"/>'
            '<line x1="245" y1="120" x2="245" y2="220" stroke="#c7ccd1"/><line x1="190" y1="170" x2="300" y2="170" stroke="#c7ccd1"/>'
            '<rect x="40" y="220" width="400" height="22" fill="#e9e9e9" stroke="#9aa3ab"/>'
            '<rect y="242" width="480" height="48" fill="#6f9a52"/>'
            f'<text x="240" y="275" text-anchor="middle" font-size="15" fill="#ffffff" font-family="sans-serif">{cap}</text></svg>')


P('… a civil war began among them. Pakistan made several efforts to establish peace among the Afghan mujahideen, but these efforts did not prove fruitful. At last, in 1996, the Taliban conquered Kabul, then Pakistan was the first country which recognised the new government and established diplomatic relations with it. After the events of 11 September (2001), America attacked and ended the Taliban government, and in their place the government of Hamid Karzai was established.',
  '… کے درمیان خانہ جنگی شروع ہوئی۔ پاکستان نے افغان مجاہدین کے درمیان امن قائم کرنے کے لیے کئی کوششیں کیں لیکن یہ کوششیں نتیجہ خیز ثابت نہ ہوئیں۔ آخرکار 1996ء میں طالبان نے کابل فتح کیا تو پاکستان پہلا ملک تھا جس نے نئی حکومت کو تسلیم کیا اور اُن سے سفارتی تعلقات قائم کیے۔ 11 ستمبر (2001ء) کے واقعات کے بعد امریکہ نے حملہ کر کے طالبان حکومت کا خاتمہ کر دیا اور ان کی جگہ حامد کرزئی کی حکومت قائم ہوئی۔',
  '… ترمنځ کورنۍ جګړه پیل شوه. پاکستان د افغان مجاهدینو ترمنځ د سولې د ټینګولو لپاره څو هڅې وکړې، خو دا هڅې ګټورې ثابتې نه شوې. بالاخره په ۱۹۹۶ز کې طالبانو کابل فتح کړ، نو پاکستان لومړی هېواد و چې نوی حکومت یې په رسمیت وپېژانده او ورسره یې ډیپلوماتیکې اړیکې ټینګې کړې. د ۱۱ سپتمبر (۲۰۰۱ز) له پېښو وروسته امریکا برید وکړ او د طالبانو حکومت یې پای ته ورساوه، او د هغوی پر ځای د حامد کرزي حکومت جوړ شو.')
P('As before, Pakistan recognised the Karzai government too and established diplomatic relations with it. Since Hamid Karzai is himself a friend of Pakistan, and Pakistan too has always supported the government of Hamid Karzai, therefore very good relations have now been established between Pakistan and Afghanistan.',
  'پاکستان نے حسبِ سابق کرزئی حکومت کو بھی تسلیم کیا اور اُس سے سفارتی تعلقات قائم کیے۔ حامد کرزئی چونکہ بذاتِ خود پاکستان کے دوست ہیں اور پھر پاکستان نے ہمیشہ حامد کرزئی کی حکومت کی حمایت کی لہٰذا اب پاکستان اور افغانستان کے درمیان بہت اچھے تعلقات استوار ہو گئے ہیں۔',
  'پاکستان د پخوا په څېر د کرزي حکومت هم په رسمیت وپېژانده او ورسره یې ډیپلوماتیکې اړیکې ټینګې کړې. څرنګه چې حامد کرزی پخپله د پاکستان دوست دی، او پاکستان هم تل د حامد کرزي د حکومت ملاتړ کړی، نو اوس د پاکستان او افغانستان ترمنځ ډېرې ښې اړیکې ټینګې شوې دي.')
H('6. Pakistan–Saudi Arabia relations', '6۔ پاکستان سعودی عرب تعلقات', '۶. د پاکستان او سعودي عربستان اړیکې')
P('The relations of Pakistan and Saudi Arabia are very old. The government of Saudi Arabia gave full support to the Muslim League and the Muslims even during the Pakistan Movement, and when Pakistan came into being, the people and government of Saudi Arabia celebrated the establishment of Pakistan. Saudi Arabia is one of those few countries which recognised Pakistan at the very beginning.',
  'پاکستان اور سعودی عرب کے تعلقات بہت دیرینہ ہیں۔ سعودی عرب کی حکومت نے تحریکِ پاکستان کے دوران بھی مسلم لیگ اور مسلمانوں کی بھرپور حمایت کی اور جب پاکستان معرضِ وجود میں آیا تو سعودی عرب کے عوام اور حکومت نے پاکستان کے قیام پر خوشیاں منائیں۔ سعودی عرب اُن چند ممالک میں سے ایک ہے جنھوں نے ابتداء ہی میں پاکستان کو تسلیم کیا۔',
  'د پاکستان او سعودي عربستان اړیکې ډېرې زړې دي. د سعودي عربستان حکومت د پاکستان د غورځنګ پر مهال هم د مسلم لیګ او مسلمانانو بشپړ ملاتړ وکړ، او کله چې پاکستان رامنځته شو، د سعودي عربستان خلکو او حکومت د پاکستان پر جوړېدو خوښۍ ولمانځلې. سعودي عربستان په هغو څو هېوادونو کې یو دی چې له پیله یې پاکستان په رسمیت وپېژانده.')
t.visual('pak12-faisal-mosque', mosque_svg('Faisal Mosque, Islamabad'), mosque_svg('فیصل مسجد، اسلام آباد'), mosque_svg('فیصل جومات، اسلام‌اباد'), 480 / 290)
P('The pleasant relations between Pakistan and Saudi Arabia kept becoming stronger and stronger with time, and whenever Pakistan faced any problem, Saudi Arabia always gave Pakistan diplomatic, moral and economic help. These relations obtained further strength in the period of President General Zia-ul-Haq. The special reason for this was that Zia-ul-Haq also had a personal relationship with the royal family of Saudi Arabia. In the period of General Zia-ul-Haq’s government Saudi Arabia issued thousands of visas for Pakistani people of the employed class and started several important projects in Pakistan. With the financial assistance of Saudi Arabia itself, the magnificent Faisal Mosque and the International Islamic University too were established in Islamabad.',
  'پاکستان اور سعودی عرب کے درمیان خوشگوار تعلقات وقت کے ساتھ مضبوط سے مضبوط تر ہوتے گئے اور جب بھی پاکستان کو کوئی مسئلہ درپیش ہوا، سعودی عرب نے ہمیشہ پاکستان کی سفارتی، اخلاقی اور معاشی مدد کی۔ ان تعلقات کو صدر جنرل ضیاء الحق کے دور میں مزید تقویت حاصل ہوئی۔ اس کی خاص وجہ ضیاء الحق اور سعودی عرب کے شاہی خاندان میں ذاتی تعلق بھی تھا۔ جنرل ضیاء الحق کے دورِ حکومت میں سعودی عرب نے پاکستانی ملازمت پیشہ افراد کے لیے ہزاروں ویزے جاری کیے اور پاکستان میں کئی اہم منصوبے شروع کیے۔ سعودی عرب ہی کی مالی اعانت سے اسلام آباد میں شاندار فیصل مسجد اور بین الاقوامی اسلامی یونیورسٹی بھی قائم کی گئی ہے۔',
  'د پاکستان او سعودي عربستان ترمنځ ښې اړیکې د وخت سره پیاوړې او لا پیاوړې شوې، او کله چې پاکستان ته کومه ستونزه پېښه شوې، سعودي عربستان تل له پاکستان سره ډیپلوماتیکه، اخلاقي او اقتصادي مرسته کړې. دې اړیکو د ولسمشر جنرل ضیاء الحق په دوره کې لا ډېر ځواک وموند. ځانګړی لامل یې دا هم و چې د ضیاء الحق او د سعودي عربستان د شاهي کورنۍ ترمنځ شخصي اړیکه وه. د جنرل ضیاء الحق د واکمنۍ په دوره کې سعودي عربستان د پاکستاني کارکوونکو لپاره زرګونه ویزې صادرې کړې او په پاکستان کې یې څو مهمې پروژې پیل کړې. د سعودي عربستان په مالي مرسته په اسلام‌اباد کې ښکلی فیصل جومات او نړیوال اسلامي پوهنتون هم جوړ شوي.')
P('Military co-operation between Saudi Arabia and Pakistan too continues. Pakistan keeps giving Saudi Arabia various kinds of assistance in the defence sector. In 1998, when Pakistan carried out the atomic test and the international community imposed various kinds of sanctions on Pakistan, Saudi Arabia provided oil worth crores free for several years to reduce Pakistan’s economic problems. From the very beginning of the twenty-first century the international community, Saudi Arabia and Pakistan have had to face international terrorism. In the war against terrorism complete harmony is found between Saudi Arabia and Pakistan.',
  'سعودی عرب اور پاکستان کے درمیان فوجی تعاون بھی برقرار ہے۔ پاکستان سعودی عرب کو دفاع کے شعبے میں مختلف قسم کی اعانت دیتا رہتا ہے۔ 1998ء میں جب پاکستان نے ایٹمی تجربہ کیا اور بین الاقوامی برادری نے پاکستان پر کئی قسم کی پابندیاں لگائیں تو سعودی عرب نے پاکستان کے معاشی مسائل کو کم کرنے کے لیے کئی سال تک کروڑوں کا تیل مفت فراہم کیا۔ اکیسویں صدی کی ابتداء ہی سے بین الاقوامی برادری، سعودی عرب اور پاکستان کو بین الاقوامی دہشت گردی کا سامنا کرنا پڑا۔ دہشت گردی کے خلاف جنگ میں سعودی عرب اور پاکستان کے درمیان مکمل ہم آہنگی پائی جاتی ہے۔',
  'د سعودي عربستان او پاکستان ترمنځ پوځي همکاري هم دوام لري. پاکستان سعودي عربستان ته په دفاعي برخه کې بېلابېلې مرستې ورکوي. په ۱۹۹۸ز کې کله چې پاکستان اټومي ازموینه وکړه او نړیوالې ټولنې پر پاکستان بېلابېل بندیزونه ولګول، سعودي عربستان د پاکستان د اقتصادي ستونزو د کمولو لپاره څو کاله کروړونه تېل وړیا ورکړل. د یوویشتمې پېړۍ له پیله نړیواله ټولنه، سعودي عربستان او پاکستان له نړیوالې ترهګرۍ سره مخ شول. د ترهګرۍ پر ضد جګړه کې د سعودي عربستان او پاکستان ترمنځ بشپړه همغږي شته.')
P('On 8 October 2005 a devastating earthquake came in Pakistan, and there was immense loss of life and property. At that difficult time Saudi Arabia helped enthusiastically.',
  '8، اکتوبر 2005ء کو پاکستان میں جو تباہ کن زلزلہ آیا اور بے انتہا جانی و مالی نقصان ہوا۔ اُس مشکل وقت میں سعودی عرب نے بڑھ چڑھ کر مدد کی۔',
  'د ۲۰۰۵ز د اکتوبر په ۸مه په پاکستان کې ویجاړونکې زلزله راغله او بې‌حده ځاني او مالي زیان واوښت. په هغه سخت وخت کې سعودي عربستان په ډېره مینه مرسته وکړه.')
H('Review of international conditions — successes and failures of Pakistan’s foreign relations', 'بین الاقوامی حالات کا جائزہ — پاکستان کے خارجہ تعلقات کی کامیابیاں اور ناکامیاں', 'د نړیوالو حالاتو کتنه — د پاکستان د بهرنیو اړیکو بریاوې او ناکامۍ')
P('After the Second World War the cold war began in international politics and the world was divided into two opposing alliance blocs. One was given the name of the capitalist or Western alliance and the other of the socialist (communist) or Eastern alliance. The head of the first bloc was America, while that of the second was Russia. After a long cold war, in December 1991 the Soviet Union (communist Russia) came to an end, and thus America remained the sole superpower in the world.',
  'دوسری جنگِ عظیم کے بعد بین الاقوامی سیاست میں سرد جنگ کا آغاز ہوا اور دُنیا دو مخالف اتحادی بلاکوں میں تقسیم ہو گئی۔ ایک کو سرمایہ دارانہ یا مغربی اتحاد اور دوسرے کو اشتراکی (کمیونسٹ) یا مشرقی اتحاد کا نام دیا گیا۔ پہلے بلاک کا سربراہ امریکہ جبکہ دوسرے کا روس تھا۔ ایک طویل سرد جنگ کے بعد دسمبر 1991ء میں سوویٹ یونین (کمیونسٹ روس) کا خاتمہ ہوا اور یوں دُنیا میں امریکہ واحد سُپر پاور رہ گیا۔',
  'له دویمې نړیوالې جګړې وروسته په نړیوال سیاست کې سړه جګړه پیل شوه او نړۍ په دوو مخالفو متحدو بلاکونو ووېشل شوه. یوه ته پانګوال یا لوېدیځ اتحاد او بل ته سوسیالیستي (کمونیستي) یا ختیځ اتحاد نوم ورکړل شو. د لومړي بلاک مشر امریکا او د دویم روسیه وه. له یوې اوږدې سړې جګړې وروسته د ۱۹۹۱ز په ډسمبر کې شوروي اتحاد (کمونیستي روسیه) پای ته ورسېد، او په دې ډول په نړۍ کې امریکا یوازینی سوپر ځواک پاتې شو.')
P('This new turn of international politics gave America a decisive role, because of which severe difficulties befell the forces and countries opposed to America, because in these new conditions America was not ready to tolerate any opposition. In these conditions the Muslim countries in particular faced considerable difficulties.',
  'بین الاقوامی سیاست کے اس نئے رُخ نے امریکہ کو فیصلہ کُن کردار بخش دیا جس کی وجہ سے امریکہ مخالف قوتوں اور ممالک کو سخت دُشواریاں لاحق ہوئیں کیونکہ ان نئے حالات میں امریکہ کسی بھی مخالفت کو برداشت کرنے کے لیے تیار نہیں۔ ان حالات میں خاص طور پر مسلمان ملکوں کو کافی دُشواریاں درپیش ہوئیں۔',
  'د نړیوال سیاست دې نوي لوري امریکا ته پرېکنده رول ورکړ، چې له امله یې امریکا مخالفو ځواکونو او هېوادونو ته سختې ستونزې پېښې شوې، ځکه په دې نویو حالاتو کې امریکا د هېڅ مخالفت زغملو ته چمتو نه ده. په دې حالاتو کې په ځانګړي ډول مسلمانو هېوادونو ته ډېرې ستونزې پېښې شوې.')
P('Because of the suicide attacks on America on 11 September 2001, Afghanistan became the target of America and its allied countries, and in 2003 Iraq was attacked. Before the attack on Iraq, in the various forums (Forum) of the United Nations, America’s own allied countries France and Germany strongly opposed the American attack on Iraq, because of which America’s relations with these countries became strained to a considerable extent, but despite this opposition Iraq fell victim to the American attack. America’s relations with Iran have been bad since the time of the Islamic revolution',
  '11، ستمبر 2001ء میں امریکہ پر خودکش حملوں کی وجہ سے افغانستان، امریکہ اور اُس کے اتحادی ملکوں کا نشانہ بنا اور 2003ء میں عراق پر حملہ کیا گیا۔ عراق پر حملے سے پہلے اقوامِ متحدہ کے مختلف فورم (Forum) پر امریکہ ہی کے اتحادی ممالک فرانس اور جرمنی نے عراق پر امریکی حملے کی سخت مخالفت کی۔ جس کی وجہ سے ان ممالک کے ساتھ امریکہ کے تعلقات کافی حد تک کشیدہ ہوئے لیکن باوجود اس مخالفت کے عراق امریکی حملے کا شکار رہا۔ امریکہ کے ایران کے ساتھ اسلامی انقلاب کے وقت سے تعلقات خراب ہیں',
  'د ۲۰۰۱ز د سپتمبر په ۱۱مه پر امریکا د ځانمرګو بریدونو له امله افغانستان د امریکا او د هغې د متحدو هېوادونو په نښه شو، او په ۲۰۰۳ز کې پر عراق برید وشو. پر عراق له برید مخکې د ملګرو ملتونو په بېلابېلو فورمونو (Forum) کې د امریکا خپلو متحدو هېوادونو فرانسې او جرمني پر عراق د امریکايي برید سخت مخالفت وکړ، چې له امله یې له دې هېوادونو سره د امریکا اړیکې تر ډېره بریده ترینګلې شوې، خو د دې مخالفت سره سره عراق د امریکايي برید ښکار شو. د امریکا اړیکې له ایران سره د اسلامي انقلاب له وخته خرابې دي')
